effect.shader:
// O buffer guarda a distância como fração deste teto (16 bits em dois canais de 8).
const float TETO = 16383.0;

vec2 guardar(float d) {
    float v = d / TETO;
    float baixo = fract(v * 255.0);
    return vec2(v - baixo / 255.0, baixo);
}

float ler(vec2 rg) {
    return (rg.x + rg.y / 255.0) * TETO;
}

// O smoothstep com as pontas em qualquer ordem (o GLSL não garante o resultado com e0 > e1).
float degrau(float e0, float e1, float x) {
    float t = clamp((x - e0) / (e1 - e0), 0.0, 1.0);
    return t * t * (3.0 - 2.0 * t);
}

void main() {
    // "Pixels de 1024²" → pixels deste buffer.
    float escala = length(acResolution) / length(vec2(1024.0));
    float inicio = offset * escala;
    float largura = width * escala;
    float alcance = inicio + largura;
    int n = max(1, int(alcance));
    float longe = alcance * 2.0;

    if (acPass == 0) {
        // Na linha: o pixel opaco mais perto, de −n a n − 1. Do centro para fora, o primeiro achado é o menor.
        float melhor = longe;
        for (int k = 0; k <= n; k++) {
            if (texture(inputImg, acScreenNorm + vec2(-float(k) * acTexelSize.x, 0.0)).a > 0.0
                || (k < n && texture(inputImg, acScreenNorm + vec2(float(k) * acTexelSize.x, 0.0)).a > 0.0)) {
                melhor = float(k);
                break;
            }
        }
        fragColor = vec4(guardar(melhor), 0.0, 0.0);
        return;
    }

    // Na coluna: o menor √(dx² + dy²), de −n a n − 1 linhas; a ponta +n (de fora) é a de CIMA na tela, como no AM.
    float sentido = acEntradaDePe == 1 ? 1.0 : -1.0;
    float melhor = 1e9;
    for (int k = 0; k <= n; k++) {
        float dy = float(k);
        if (dy >= melhor) break;    // daqui para fora nada fica mais perto
        float dx = ler(texture(distX, acScreenNorm - vec2(0.0, sentido * dy * acTexelSize.y)).rg);
        melhor = min(melhor, length(vec2(dx, dy)));
        if (k < n) {
            dx = ler(texture(distX, acScreenNorm + vec2(0.0, sentido * dy * acTexelSize.y)).rg);
            melhor = min(melhor, length(vec2(dx, dy)));
        }
    }

    vec4 base = texture(inputImg, acScreenNorm);
    vec4 camada = vec4(base.rgb * base.a, base.a) * fill;   // pré-multiplicada

    vec4 c = vec4(0.0);
    if (largura > 0.0) {
        float aa = 1.0 / largura / 2.0;
        float p = clamp((melhor - inicio) / largura, 0.0, 1.0);
        float mascara = fade
            ? degrau(1.0, 0.0, p) * degrau(0.0, aa, p)
            : degrau(0.0, aa, p) * degrau(1.0, 1.0 - aa, p);
        c = mix(color1, color2, p) * (alpha * mascara * (1.0 - base.a));
    }

    vec4 saida = camada * (1.0 - c.a) + c;
    fragColor = saida.a > 0.0 ? vec4(saida.rgb / saida.a, saida.a) : vec4(0.0);
}
